sp_widget.client_script:
api.controller = function($window) {

    var c = this;

    c.goToApply = function() {

        if (!c.data.job)
            return;

        $window.location.href =
            '?id=aegis_apply&requisition_id=' +
            c.data.job.sys_id;
    };

};

sp_widget.css:
.aegis-detail {
  max-width: 1280px;
  margin: 30px auto;
  padding: 40px;

  background: #ffffff;

  border-radius: 36px;

  box-shadow:
    0 20px 60px rgba(0,0,0,.08);
}

/* BACK LINK */

.back-link {
  display: inline-flex;
  align-items: center;
  gap: 8px;

  text-decoration: none;
  color: #6b7280;

  font-weight: 600;

  margin-bottom: 28px;
}

.back-link:hover {
  color: #0f3b2f;
}

/* GRID */

.detail-grid {
  display: grid;
  grid-template-columns: minmax(0,1fr) 420px;
  gap: 40px;
  align-items: start;
}

/* LEFT CONTENT */

.content-area {
  min-width: 0;
}

/* DEPARTMENT CHIP */

.role-badge {
  display: inline-flex;

  background: #eef2ee;

  color: #0f3b2f;

  border-radius: 999px;

  padding: 10px 20px;

  font-weight: 700;

  margin-bottom: 18px;
}

/* TITLE */

.detail-head h1 {
  font-size: 62px;

  line-height: 1.05;

  color: #102a22;

  margin: 0 0 24px;
}

/* META PILLS */

.meta-row {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;

  margin-bottom: 30px;
}

.meta-pill {
  background: #f8f8f8;

  border: 1px solid #e5e7eb;

  border-radius: 999px;

  padding: 10px 18px;

  font-size: 14px;

  font-weight: 600;

  color: #374151;
}

/* JOB DESCRIPTION CARD */

.section-card {

  background: #ffffff;

  border-radius: 28px;

  padding: 32px;

  border: 1px solid #f0f0f0;

  box-shadow:
      0 10px 30px rgba(0,0,0,.06);
}

.section-card h2 {

  font-size: 40px;

  color: #0f3b2f;

  margin: 0 0 18px;
}

/* JOB DESCRIPTION CONTENT */

.rich-jd {

  color: #4b5563;

  font-size: 17px;

  line-height: 1.7;
}

.rich-jd > *:first-child {
  margin-top: 0;
}

.rich-jd > *:last-child {
  margin-bottom: 0;
}

.rich-jd h1 {

  color: #0f3b2f;

  font-size: 34px;

  margin: 18px 0 10px;
}

.rich-jd h2 {

  color: #0f3b2f;

  font-size: 28px;

  margin: 22px 0 10px;
}

.rich-jd h3 {

  color: #0f3b2f;

  font-size: 22px;

  margin: 20px 0 10px;
}

.rich-jd strong {
  color: #111827;
}

.rich-jd p {

  margin: 0 0 12px;

  line-height: 1.7;
}

.rich-jd ul {

  margin: 8px 0 16px;

  padding-left: 28px;
}

.rich-jd li {

  margin-bottom: 6px;

  line-height: 1.7;
}

.rich-jd h2 + ul,
.rich-jd h3 + ul {

  margin-top: 4px;
}

/* SIDEBAR */

.side-card {

  background:
      linear-gradient(
          135deg,
          #012b22 0%,
          #003a2d 55%,
          #01271f 100%
      );

  color: white;

  border-radius: 30px;

  padding: 28px;

  position: sticky;

  top: 24px;

  height: fit-content;

  align-self: start;

  overflow: hidden;

  box-shadow:
      0 18px 40px rgba(0,0,0,.18);
}

.blob-mini {

  position: absolute;

  width: 140px;
  height: 140px;

  border-radius: 50%;

  background: #d4a531;

  opacity: .18;

  top: -40px;
  right: -40px;
}

.side-card h4 {

  color: #aabbb2;

  text-transform: uppercase;

  letter-spacing: 3px;

  font-size: 12px;

  margin-bottom: 22px;
}

.side-fact {

  display: flex;

  justify-content: space-between;

  align-items: center;

  padding: 12px 0;

  border-bottom:
      1px solid rgba(255,255,255,.08);
}

.side-fact span:first-child {
  color: #aabbb2;
}

.side-fact span:last-child {
  font-weight: 700;
}

/* BENEFITS */

.benefits-box {

  margin-top: 24px;

  background:
      rgba(255,255,255,.05);

  border-radius: 20px;

  padding: 20px;
}

.benefits-box h5 {

  margin: 0 0 14px;

  font-size: 16px;

  font-weight: 700;
}

.benefits-box ul {

  margin: 0;

  padding-left: 18px;
}

.benefits-box li {

  margin-bottom: 10px;

  color: #d8e4dc;

  font-size: 14px;
}

/* BUTTON */

.aegis-btn-primary {

  width: 100%;

  height: 58px;

  border: none;

  border-radius: 999px;

  background:
      linear-gradient(
          135deg,
          #e16b4d,
          #d45a39
      );

  color: white;

  font-size: 17px;

  font-weight: 700;

  cursor: pointer;

  margin-top: 24px;

  transition: all .25s ease;
}

.aegis-btn-primary:hover {

  transform: translateY(-2px);

  box-shadow:
      0 12px 28px rgba(225,107,77,.35);
}

.side-note {

  margin-top: 14px;

  color: #9fb3a6;

  font-size: 13px;

  line-height: 1.6;
}

/* MOBILE BUTTON */

.apply-mobile {
  display: none;
}

/* RESPONSIVE */

@media (max-width: 992px) {

  .aegis-detail {
    padding: 20px;
  }

  .detail-grid {
    grid-template-columns: 1fr;
  }

  .side-card {
    position: relative;
    top: 0;
  }

  .detail-head h1 {
    font-size: 42px;
  }

  .section-card {
    padding: 24px;
  }

  .section-card h2 {
    font-size: 30px;
  }

  .apply-mobile {
    display: block;
    margin-top: 24px;
  }
}

sp_widget.script:
(function() {

    data.job = null;

    var reqId =
        $sp.getParameter('sys_id');

    if (!reqId)
        return;

    function convertMarkdownToHtml(text) {

        if (!text)
            return '';

        text = text.replace(
            /^### (.*$)/gim,
            '<h3>$1</h3>'
        );

        text = text.replace(
            /^## (.*$)/gim,
            '<h2>$1</h2>'
        );

        text = text.replace(
            /^# (.*$)/gim,
            '<h1>$1</h1>'
        );

        text = text.replace(
            /\*\*(.*?)\*\*/g,
            '<strong>$1</strong>'
        );

        text = text.replace(
            /^- (.*)$/gim,
            '<li>$1</li>'
        );

        text = text.replace(
            /(<li>.*<\/li>)/gs,
            '<ul>$1</ul>'
        );

        text = text.replace(
            /\n\n/g,
            '<br><br>'
        );

        return text;
    }

    var gr =
        new GlideRecord(
            'x_snc_aegis_job_requisition'
        );

    if (!gr.get(reqId))
        return;

    var jdText = '';

    var jdGr =
        new GlideRecord(
            'x_snc_aegis_job_description'
        );

    jdGr.addQuery(
        'requisition',
        reqId
    );

    jdGr.orderByDesc('version');

    jdGr.setLimit(1);

    jdGr.query();

    if (jdGr.next()) {

        jdText =
            jdGr.getValue('jd_text') || '';
    }

    data.job = {

        sys_id:
            gr.getUniqueValue(),

        role_title:
            gr.getValue('role_title'),

        department:
            gr.getValue('department'),

        level:
            gr.getValue('level'),

        experience_required_years:
            gr.getValue(
                'experience_required_years'
            ),

        jd_text:
            convertMarkdownToHtml(
                jdText
            )
    };

})();
